 if(selectedTab==1){viewer=new ArchiveViewer(this,client,cameras,dark,new ArchiveViewer.Listener(){public void onDownload(ApiClient.Recording r,boolean high,boolean share){export(r,high,share);}public void onFocus(ApiClient.Camera camera,long at){showArchiveAt(camera,at);}});content.addView(viewer,new FrameLayout.LayoutParams(-1,-1));if(!started)viewer.suspend();return;}
 if(cameras.isEmpty()){TextView empty=text("Нет доступных камер",18);empty.setGravity(Gravity.CENTER);content.addView(empty,new FrameLayout.LayoutParams(-1,-1));return;}
 ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);scroll.setPadding(0,dp(8),0,dp(8));LiveWall wall=new LiveWall(this,ids->{Map<String,ApiClient.Camera> byId=new HashMap<>();for(ApiClient.Camera c:cameras)byId.put(c.id,c);cameras.clear();for(String id:ids){ApiClient.Camera c=byId.get(id);if(c!=null)cameras.add(c);}saveOrder();});liveWall=wall;wall.setColumns(feed?1:2);scroll.addView(wall);content.addView(scroll,new FrameLayout.LayoutParams(-1,-1));final int requestId=generation;
