 private void settings(){String[] items={"Тема оформления","Обновить камеры","Забыть сохранённый пароль","Выйти из аккаунта","Диагностика"};new AlertDialog.Builder(this).setTitle("Настройки").setItems(items,(d,n)->{if(n==0){new AlertDialog.Builder(this).setTitle("Тема оформления").setItems(new String[]{"Как в телефоне","Светлая","Тёмная"},(dialog,index)->{getPreferences(0).edit().putString("theme",new String[]{"system","light","dark"}[index]).apply();palette();showHome(tab);}).show();}else if(n==1){int id=++generation;io.execute(()->{try{loadCameras(id);}catch(Exception e){ui(id,()->error(safeError(e)));}});}else if(n==2){credentials.clear();Toast.makeText(this,"Сохранённый пароль удалён",Toast.LENGTH_SHORT).show();}else if(n==4){String log=getPreferences(0).getString("last_crash","Ошибок Java не зафиксировано. Нативные сбои видеодекодера сюда не попадают.");new AlertDialog.Builder(this).setTitle("Диагностика").setMessage(log).setPositiveButton("Закрыть",null).setNeutralButton("Отправить",(d1,w)->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,log),"Отправить диагностику"))).show();}else{credentials.clear();closeSocket();auth=null;group=null;uid=null;cameras.clear();client=null;showLogin();}}).show();}
 private void loadStream(ApiClient.Camera camera,boolean high,VLCVideoLayout view,TextView state,int requestId){io.execute(()->{try{if(requestId!=generation)return;watch(camera.id);if(requestId!=generation)return;if(client.requiresDynamic(camera,high))client.ensureDynamic(camera);String url=client.liveUrl(camera,high);ui(requestId,()->attach(view,url,state,requestId));}catch(Exception e){ui(requestId,()->{state.setText("Нет связи · нажмите для повтора");state.setTextColor(Color.rgb(232,139,114));state.setOnClickListener(v->{state.setText("Подключение…");loadStream(camera,high,view,state,requestId);});});}});}
 private void attach(VLCVideoLayout view,String url,TextView state,int requestId){if(destroyed||requestId!=generation||!started)return;MediaPlayer player=new MediaPlayer(vlc);players.add(player);player.attachViews(view,null,false,true);int[] attempts={0};player.setEventListener(event->{if(event.type==MediaPlayer.Event.Playing)ui(requestId,()->{state.setText("● В эфире");state.setTextColor(accent);});else if(event.type==MediaPlayer.Event.Buffering)ui(requestId,()->state.setText(event.getBuffering()<100?"Буферизация…":"● В эфире"));else if(event.type==MediaPlayer.Event.EncounteredError){if(destroyed||requestId!=generation)return;ui(requestId,()->state.setText("Потеря связи · переподключение…"));handler.postDelayed(()->{if(requestId!=generation||destroyed||!players.contains(player)||!started)return;if(attempts[0]++<3){player.stop();player.play();}else{state.setText("Нет связи · нажмите для повтора");state.setOnClickListener(v->{if(destroyed||requestId!=generation||!players.contains(player))return;attempts[0]=0;state.setText("Подключение…");player.stop();player.play();});}},2000);}});Media source=new Media(vlc,Uri.parse(url));player.setMedia(source);source.release();player.setVolume(0);if(started)player.play();}
 private void showCamera(ApiClient.Camera camera,boolean high){LinearLayout page=screen("camera",()->showCamera(camera,high),true);page.setPadding(0,0,0,0);int requestId=generation;FrameLayout stage=new FrameLayout(this);stage.setBackgroundColor(Color.BLACK);page.addView(stage,new LinearLayout.LayoutParams(-1,-1));VLCVideoLayout video=new VLCVideoLayout(this);stage.addView(video,new FrameLayout.LayoutParams(-1,-1));stage.addView(new ZoomGestureOverlay(this,video,()->showHome(0),null),new FrameLayout.LayoutParams(-1,-1));LinearLayout top=row();top.setPadding(dp(12),dp(6),dp(12),dp(6));top.setBackgroundColor(0x66000000);Button back=button("‹",()->showHome(0));back.setTextColor(Color.WHITE);back.setBackground(shape(0x55000000,20));top.addView(back,new LinearLayout.LayoutParams(dp(48),dp(44)));TextView name=text(camera.name,18);name.setTextColor(Color.WHITE);top.addView(name,new LinearLayout.LayoutParams(0,-2,1));LiveStatus state=new LiveStatus();top.addView(state,new LinearLayout.LayoutParams(dp(30),dp(30)));stage.addView(top,new FrameLayout.LayoutParams(-1,-2,Gravity.TOP));LinearLayout controls=row();controls.setGravity(Gravity.CENTER);controls.setPadding(dp(12),dp(6),dp(12),dp(6));controls.setBackgroundColor(0x66000000);Button quality=button(high?"4К → SD":"SD → 4К",()->showCamera(camera,!high)),shot=button("Снимок",()->snapshot(video,camera.name)),archive=button("Архив",()->showArchive(camera,0));for(Button control:new Button[]{quality,shot,archive}){control.setTextColor(Color.WHITE);control.setBackground(shape(0x77000000,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(136),dp(44));lp.setMargins(dp(5),0,dp(5),0);controls.addView(control,lp);}stage.addView(controls,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));stage.setOnApplyWindowInsetsListener((v,insets)->{int left=insets.getSystemWindowInsetLeft(),right=insets.getSystemWindowInsetRight(),safeTop=insets.getSystemWindowInsetTop(),bottom=insets.getSystemWindowInsetBottom();if(Build.VERSION.SDK_INT>=28&&insets.getDisplayCutout()!=null){left=Math.max(left,insets.getDisplayCutout().getSafeInsetLeft());right=Math.max(right,insets.getDisplayCutout().getSafeInsetRight());safeTop=Math.max(safeTop,insets.getDisplayCutout().getSafeInsetTop());bottom=Math.max(bottom,insets.getDisplayCutout().getSafeInsetBottom());}top.setPadding(left+dp(12),safeTop+dp(6),right+dp(12),dp(6));controls.setPadding(left+dp(12),dp(6),right+dp(12),bottom+dp(6));return insets;});stage.requestApplyInsets();loadStream(camera,high,video,state,requestId);}
 private TextureView texture(View v){if(v instanceof TextureView)return (TextureView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextureView found=texture(g.getChildAt(i));if(found!=null)return found;}}return null;}
 private void snapshot(View video,String name){try{TextureView texture=texture(video);if(texture==null||!texture.isAvailable())throw new IOException();Bitmap bitmap=texture.getBitmap();if(bitmap==null)throw new IOException();media.screenshot(bitmap,name+"_"+new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss",Locale.ROOT).format(new Date()));bitmap.recycle();}catch(Exception e){error("Дождитесь изображения и повторите снимок.");}}
 private String dateLabel(long ms){return new SimpleDateFormat("dd MMM · HH:mm:ss",new Locale("ru")).format(new Date(ms));}
 private void showArchive(ApiClient.Camera camera,long day){LinearLayout page=screen("archive",()->showArchive(camera,day),false);LinearLayout bar=row();bar.addView(button("‹",()->showCamera(camera,false)),new LinearLayout.LayoutParams(dp(48),dp(46)));TextView title=text(camera.name,22);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("Дата",()->{Calendar c=Calendar.getInstance();if(day>0)c.setTimeInMillis(day);new DatePickerDialog(this,(v,y,m,d)->{Calendar chosen=Calendar.getInstance();chosen.set(y,m,d,0,0,0);chosen.set(Calendar.MILLISECOND,0);showArchive(camera,chosen.getTimeInMillis());},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}));page.addView(bar);page.addView(note(day==0?"Архив · последние записи":"Архив · "+new SimpleDateFormat("dd MMMM yyyy",new Locale("ru")).format(new Date(day))));ScrollView scroll=new ScrollView(this);LinearLayout list=col();scroll.addView(list);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView status=note("Загружаем записи…");list.addView(status);int requestId=generation;io.execute(()->{try{long end=0;if(day>0){Calendar next=Calendar.getInstance();next.setTimeInMillis(day);next.add(Calendar.DAY_OF_MONTH,1);end=next.getTimeInMillis();}List<ApiClient.Recording> rows=client.recordings(camera.id,day,end);ui(requestId,()->{list.removeAllViews();if(rows.isEmpty())list.addView(note("За это время записей нет"));for(ApiClient.Recording r:rows){LinearLayout item=col();item.setPadding(dp(12),dp(10),dp(12),dp(10));item.setBackground(shape(card,16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));list.addView(item,lp);TextView label=text(dateLabel(r.startMs),17);item.addView(label);item.addView(note(Math.max(1,(r.endMs-r.startMs)/1000)+" сек · SD / 4К"));LinearLayout actions=row();actions.addView(button("▶ Смотреть",()->showRecording(camera,r,false,0)),weight());actions.addView(button("↓ / Поделиться",()->exportMenu(r)),weight());item.addView(actions);}});}catch(Exception e){ui(requestId,()->{status.setText("Нет связи с архивом · нажмите для повтора");status.setOnClickListener(v->showArchive(camera,day));});}});}
 private void showArchiveAt(ApiClient.Camera camera,long time){int requestId=++generation;io.execute(()->{try{List<ApiClient.Recording> records=client.recordings(camera.id,time-600000,time+600000);ApiClient.Recording row=ArchiveTimeline.at(records,time);ui(requestId,()->{if(row==null)error("В этот момент нет записи");else showRecording(camera,row,false,Math.max(0,time-row.startMs));});}catch(Exception e){ui(requestId,()->error("Не удалось открыть запись"));}});}
 private void exportMenu(ApiClient.Recording r){String[] options={"Скачать SD","Скачать 4К","Отправить SD","Отправить 4К"};new AlertDialog.Builder(this).setTitle("Сохранить запись").setItems(options,(d,n)->export(r,n%2==1,n>=2)).show();}
 private void export(ApiClient.Recording record,boolean high,boolean share){Toast.makeText(this,"Готовим "+(high?"4К":"SD")+"…",Toast.LENGTH_SHORT).show();ApiClient session=client;io.execute(()->{try{String url=high?record.url:session.variants(record).lowUrl;if(url==null||url.isEmpty())throw new IOException();runOnUiThread(()->{if(destroyed||isFinishing()||isDestroyed())return;android.app.ProgressDialog progress=new android.app.ProgressDialog(this);progress.setTitle(share?"Подготовка к отправке":"Скачивание записи");progress.setProgressStyle(android.app.ProgressDialog.STYLE_HORIZONTAL);progress.setMax(100);progress.setCancelable(false);progress.setButton(android.app.ProgressDialog.BUTTON_NEGATIVE,"В фоне",(d,w)->{});progress.show();media.download(url,"Камера_"+record.cameraId+"_"+new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss",Locale.ROOT).format(new Date(record.startMs))+"_"+(high?"4K":"SD"),share,new MediaFiles.Progress(){public void onProgress(long done,long total){if(total>0){progress.setIndeterminate(false);progress.setProgress((int)(done*100/total));}else progress.setIndeterminate(true);}public void onComplete(Uri uri){progress.dismiss();Toast.makeText(MainActivity.this,"Сохранено в «Загрузки / Камеры»",Toast.LENGTH_LONG).show();}public void onError(String message){progress.dismiss();error(message);}});});}catch(Exception e){runOnUiThread(()->error(high?"Не удалось скачать запись":"Для этой записи SD недоступно. Выберите 4К."));}});}
 private void showRecording(ApiClient.Camera camera,ApiClient.Recording record,boolean high,long start){LinearLayout page=screen("recording",()->showRecording(camera,record,high,recordingVideo==null?Math.max(start,stoppedRecordingPosition):recordingVideo.getCurrentPosition()),false);int requestId=generation;stoppedRecordingPosition=start;LinearLayout bar=row();bar.addView(button("‹ Архив",()->showArchive(camera,0)));bar.addView(text(camera.name,19),new LinearLayout.LayoutParams(0,-2,1));page.addView(bar);page.addView(note(dateLabel(record.startMs)));FrameLayout stage=new FrameLayout(this);stage.setBackgroundColor(Color.BLACK);VideoView video=new VideoView(this);recordingVideo=video;stage.addView(video,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));ZoomGestureOverlay overlay=new ZoomGestureOverlay(this,video,()->{boolean landscape=getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;setRequestedOrientation(landscape?ActivityInfo.SCREEN_ORIENTATION_PORTRAIT:ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);},null);stage.addView(overlay,new FrameLayout.LayoutParams(-1,-1));page.addView(stage,new LinearLayout.LayoutParams(-1,0,1));TextView status=note("Подготавливаем "+(high?"4К":"SD")+"…");page.addView(status);SeekBar seek=new SeekBar(this);seek.setMax((int)Math.min(Integer.MAX_VALUE,Math.max(1,record.endMs-record.startMs)));page.addView(seek);boolean[] dragging={false};seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int value,boolean user){}public void onStartTrackingTouch(SeekBar s){dragging[0]=true;}public void onStopTrackingTouch(SeekBar s){video.seekTo(s.getProgress());dragging[0]=false;}});TextView elapsed=note("00:00");page.addView(elapsed);LinearLayout playback=row();playback.addView(button("−10 с",()->video.seekTo(Math.max(0,video.getCurrentPosition()-10000))),weight());Button pause=button("Ⅱ Пауза",()->{});pause.setOnClickListener(v->{if(video.isPlaying()){video.pause();pause.setText("▶ Пуск");status.setText("Пауза");}else{video.start();pause.setText("Ⅱ Пауза");}});playback.addView(pause,weight());playback.addView(button("+10 с",()->video.seekTo(Math.min(seek.getMax(),video.getCurrentPosition()+10000))),weight());page.addView(playback);LinearLayout tools=row();tools.addView(button(high?"4К → SD":"SD → 4К",()->showRecording(camera,record,!high,Math.max(0,video.getCurrentPosition()))),weight());tools.addView(button("Скачать",()->export(record,high,false)),weight());tools.addView(button("Отправить",()->export(record,high,true)),weight());page.addView(tools);
 video.setOnPreparedListener(mp->{if(requestId!=generation)return;mp.setVolume(0,0);if(start>0)video.seekTo((int)Math.min(Integer.MAX_VALUE,start));if(started)video.start();status.setText("Воспроизведение · "+(high?"4К":"SD"));});video.setOnInfoListener((mp,what,extra)->{if(requestId!=generation)return false;if(what==android.media.MediaPlayer.MEDIA_INFO_BUFFERING_START)status.setText("Буферизация…");if(what==android.media.MediaPlayer.MEDIA_INFO_BUFFERING_END)status.setText("Воспроизведение · "+(high?"4К":"SD"));return false;});video.setOnErrorListener((mp,what,extra)->{if(requestId==generation){status.setText("Ошибка воспроизведения · нажмите для повтора");status.setOnClickListener(v->showRecording(camera,record,high,start));}return true;});video.setOnCompletionListener(mp->{status.setText("Запись закончилась");pause.setText("▶ Пуск");});io.execute(()->{try{String url=high?record.url:client.variants(record).lowUrl;if(url==null||url.isEmpty()){ui(requestId,()->status.setText("SD для этой записи отсутствует · переключитесь на 4К"));return;}ui(requestId,()->video.setVideoURI(Uri.parse(url)));}catch(Exception e){ui(requestId,()->{status.setText("Нет связи · нажмите для повтора");status.setOnClickListener(v->showRecording(camera,record,high,start));});}});Runnable ticker=new Runnable(){public void run(){if(requestId!=generation||isFinishing())return;int pos=Math.max(0,video.getCurrentPosition());if(!dragging[0])seek.setProgress(pos);elapsed.setText(String.format(Locale.ROOT,"%02d:%02d / %02d:%02d",pos/60000,pos/1000%60,seek.getMax()/60000,seek.getMax()/1000%60));handler.postDelayed(this,500);}};handler.post(ticker);
 }
 private void releasePlayers(){VideoView oldVideo=recordingVideo;recordingVideo=null;if(oldVideo!=null){oldVideo.setOnPreparedListener(null);oldVideo.setOnInfoListener(null);oldVideo.setOnErrorListener(null);oldVideo.setOnCompletionListener(null);try{oldVideo.stopPlayback();}catch(Exception ignored){}}List<MediaPlayer> old=new ArrayList<>(players);players.clear();for(MediaPlayer p:old)try{p.setEventListener(null);p.stop();p.detachViews();p.release();}catch(Exception ignored){}}
 @Override public void onBackPressed(){if(auth==null){super.onBackPressed();return;}if(pageName.equals("home")&&tab==0){new AlertDialog.Builder(this).setMessage("Закрыть приложение?").setNegativeButton("Остаться",null).setPositiveButton("Закрыть",(d,w)->finish()).show();}else showHome(0);}
 @Override protected void onStop(){started=false;if(viewer!=null)viewer.suspend();if(recordingVideo!=null)try{stoppedRecordingPosition=recordingVideo.getCurrentPosition();}catch(Exception ignored){}if(auth!=null){generation++;releasePlayers();resumeConnection=true;}super.onStop();}
 @Override protected void onStart(){super.onStart();started=true;if(resumeConnection&&auth!=null){resumeConnection=false;if(viewer!=null){viewer.resume();return;}if(socketReady){if(restorePage!=null)restorePage.run();}else{final int requestId=generation;io.execute(()->{try{connectSocket(requestId);ui(requestId,()->{if(started&&restorePage!=null)restorePage.run();});}catch(Exception e){ui(requestId,()->error("Соединение потеряно. Откройте камеры повторно."));}});}}}
 @Override protected void onDestroy(){destroyed=true;generation++;handler.removeCallbacksAndMessages(null);if(viewer!=null)viewer.destroy();releasePlayers();closeSocket();io.shutdownNow();media.close();vlc.release();super.onDestroy();}
